CREATE TABLE service_catalog(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT true,min_price INTEGER CHECK(min_price>0),max_price INTEGER CHECK(max_price>0),version INTEGER NOT NULL DEFAULT 0,CHECK(min_price IS NULL OR max_price IS NULL OR min_price<=max_price));
CREATE TABLE service_appointments(id TEXT PRIMARY KEY,client_id TEXT REFERENCES clients(id),customer TEXT NOT NULL,phone TEXT NOT NULL,brand TEXT NOT NULL,model TEXT NOT NULL,year INTEGER NOT NULL,plate TEXT NOT NULL DEFAULT '',color TEXT NOT NULL DEFAULT '',scheduled_on TEXT NOT NULL,start_time TEXT NOT NULL,duration INTEGER NOT NULL,notes TEXT NOT NULL DEFAULT '',items JSONB NOT NULL,total BIGINT, status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','in_progress','performed','confirmed','cancelled')),performed_on TEXT,version INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX service_calendar ON service_appointments(scheduled_on,start_time);
CREATE TABLE reported_payments(id TEXT PRIMARY KEY,target_kind TEXT NOT NULL CHECK(target_kind IN ('service','invoice','advance')),target_id TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),method TEXT NOT NULL CHECK(method IN ('cash','transfer','debit','credit')),paid_on TEXT NOT NULL,reference TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','reversed')),payload JSONB NOT NULL DEFAULT '{}',actor TEXT NOT NULL,reviewed_by TEXT,reason TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ,reversed_on TEXT);
CREATE UNIQUE INDEX reported_reference ON reported_payments(method,lower(reference)) WHERE reference<>'' AND method<>'cash' AND status IN ('pending','approved');
CREATE TABLE payment_evidence(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES reported_payments(id),name TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,content TEXT NOT NULL);
CREATE INDEX payment_evidence_parent ON payment_evidence(payment_id);
CREATE TABLE service_audit(id TEXT PRIMARY KEY,entity_id TEXT NOT NULL,action TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE reported_payment_allocations(payment_id TEXT PRIMARY KEY REFERENCES payments(id),report_id TEXT NOT NULL REFERENCES reported_payments(id));
